from fractions import Fraction as F
from pathlib import Path
import hashlib,json,subprocess

def derivative(p): return [i*p[i] for i in range(1,len(p))]
def recurrence(p,kind):
    out=[0]*(len(p)+1)
    for i,c in enumerate(p):
        out[i+1]+=c
        out[i]-=(i+(kind=='p'))*c
    return out

def horner(p,x):
    y=F(0)
    for c in reversed(p): y=y*x+c
    return y

def add(a,b): return a[0]+b[0],a[1]+b[1]
def mul(a,b):
    v=[x*y for x in a for y in b]
    return min(v),max(v)
def interval_horner(p,x):
    y=(F(0),F(0))
    for c in reversed(p): y=add(mul(y,x),(F(c),F(c)))
    return y

def exp_negative(x):
    assert 0<=x<50
    term=F(1); s=term
    for k in range(1,49):
        term*=x/k;s+=term
    h=term*x/49
    return 1/(s+h/(1-x/50)),1/s

def absupper(x): return max(abs(x[0]),abs(x[1]))
def ceiling(x,den=10**12): return F(-(-x.numerator*den//x.denominator),den)
rootnums={3:[1657568156,13433795689,44908636153],4:[760038343,7621690715,26516929955,65101340985]}
limits={3:[F('0.42962'),F('1.78302')],4:[F('1.11875'),F('4.51031')]}
p=q=[1]; out={}
for n in range(1,5):
    p=recurrence(p,'p');q=recurrence(q,'q')
    qp=derivative(q)+[0]
    assert p==[a-b for a,b in zip(q,qp)]
    if n not in rootnums: continue
    zs=[]; signs=[]
    for a in rootnums[n]:
        l,r=F(a,10**10),F(a+1,10**10)
        pl,pr=horner(p,l),horner(p,r)
        assert pl*pr<0
        signs.append([1 if pl>0 else -1,1 if pr>0 else -1])
        z=mul(interval_horner(q,(l,r)),(exp_negative(r)[0],exp_negative(l)[1]))
        assert z[0]*z[1]>0
        zs.append(z)
    A=max(map(absupper,zs))
    zs2=[(F(0),F(0))]+zs+[(F(0),F(0))]
    B=sum(absupper((b[0]-a[1],b[1]-a[0])) for a,b in zip(zs2,zs2[1:]))
    assert A<limits[n][0] and B<limits[n][1]
    out[n]={'p_ascending':p,'q_ascending':q,'bracket_endpoint_signs':signs,'A_verified_upper_rational':str(ceiling(A)),'B_verified_upper_rational':str(ceiling(B)),'A_claimed_exact_upper':str(limits[n][0]),'B_claimed_exact_upper':str(limits[n][1]),'all_exact_comparisons_pass':True}
print(json.dumps(out,indent=2))
